// THE WORDS OF A DESK POPULATION (Nov 8 2026, Desk v3): "manual coupes in Good condition from 41,400 to 81,400 miles", built from the subject's own facts, one place
function deskPopulationWordsRaw(s = {}) {
  const parts = [s.transmission ? String(s.transmission).toLowerCase() : null, s.body ? String(s.body).toLowerCase() + "s" : (!s.transmission && s.label ? String(s.label) : "cars")].filter(Boolean).join(" ");   // a car with no gearbox and no body stated is named, never "cars" (Lane F's run: the Mini's header read "These are the sales of cars")
  const tail = [s.tierName ? `in ${s.tierName} condition` : null, s.miMin != null && s.miMax != null ? `from ${n(s.miMin)} to ${n(s.miMax)} miles` : s.miMin != null ? `over ${n(s.miMin)} miles` : s.miMax != null ? `up to ${n(s.miMax)} miles` : null].filter(Boolean).join(" ");
  return [parts, tail].filter(Boolean).join(" ");
}
// the small phrases of a Desk comparable's reason (Nov 8 2026): the year, the miles and the tier against the subject, in words, one place
const NUMW = ["no", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten"];
const deskYearWordsRaw = d => { const k = Math.abs(Math.round(d)); return k === 0 ? "Same year" : `${(NUMW[k] || String(k)).replace(/^./, c => c.toUpperCase())} ${k === 1 ? "year" : "years"} ${d > 0 ? "newer" : "older"}`; };
const deskMilesWordsRaw = d => { const k = Math.round(Math.abs(d) / 100) * 100; return k < 1000 ? "about the same miles" : `${n(k)} ${d < 0 ? "fewer" : "more"} miles`; };
const deskTierWordsRaw = d => { const k = Math.abs(Math.round(d)); return `${(NUMW[k] || String(k))} condition ${k === 1 ? "tier" : "tiers"} ${d < 0 ? "better" : "worse"}`; };
export const deskAndList = xs => { const a = (xs || []).map(String); return a.length < 2 ? a.join("") : a.slice(0, -1).join(", ") + " and " + a[a.length - 1]; };
export const deskDateShort = iso => { const d = new Date(String(iso) + "T00:00:00Z"); return Number.isNaN(d.getTime()) ? String(iso) : d.toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric", timeZone: "UTC" }); };
const deskFbMatchedWordsRaw = f => { const a = ["model"]; if (f.year) a.push("year"); if (f.gearbox) a.push("gearbox"); if (f.body) a.push("body"); if (f.miles) a.push("miles"); return deskAndList(a); };
const deskFbDiffWordsRaw = f => {
  if (f.dYear) { const k = Math.abs(f.dYear); return `${k} ${k === 1 ? "year" : "years"} ${f.dYear < 0 ? "older" : "newer"}`; }
  if (f.gearboxDiff) return "a different gearbox";
  if (f.bodyDiff) return "a different body";
  if (f.dMiles != null && Math.abs(f.dMiles) >= 1000) return deskMilesWords(f.dMiles);
  if (f.milesUnknown) return "miles not stated";
  return null;
};
export const deskMoneyList = ps => { const m = (ps || []).map(x => money(x)); return m.length < 2 ? m.join("") : m.slice(0, -1).join(", ") + " and " + m[m.length - 1]; };
export const deskMonthYear = iso => { const d = new Date(String(iso) + "T00:00:00Z"); return Number.isNaN(d.getTime()) ? String(iso) : d.toLocaleDateString("en-US", { month: "long", year: "numeric", timeZone: "UTC" }); };
export const deskDateWords = iso => { const d = new Date(String(iso) + "T00:00:00Z"); return Number.isNaN(d.getTime()) ? String(iso) : d.toLocaleDateString("en-US", { month: "long", day: "numeric", year: "numeric", timeZone: "UTC" }); };
export const deskPopulationWords = W("deskPopulationWords", deskPopulationWordsRaw);
export const deskYearWords = W("deskYearWords", deskYearWordsRaw);
export const deskMilesWords = W("deskMilesWords", deskMilesWordsRaw);
